    { tooltip_id = "ability:ability_survival_flame_burst", tooltip_type = "ability", id = "ability_survival_flame_burst", name = "爆炎弹·被动", needwood = "0", needgold = "0", desc = "等级1：攻击命中时有15%概率引爆目标位置，对500范围造成全属性×4纯粹伤害。 等级2：主爆炸命中的敌人被点燃，在3秒内总计受到全属性×2.2额外伤害。再次点燃会替换旧点燃并重新持续3秒。 等级3：点燃最多叠加5层；每层拥有独立的3秒持续时间和属性快照，超过5层时替换最早到期的一层。 等级4：完整继承等级3效果，无额外变化。 等级5：主爆炸后同时喷射3颗小火球，0.5秒后落在主爆炸中心200范围内的随机位置。每颗对250范围造成全属性×3伤害，并分别施加1层点燃。", icon = "lina_dragon_slave", source_id = "proto_flame_burst" },
    { tooltip_id = "ability:ability_survival_frost_nova", tooltip_type = "ability", id = "ability_survival_frost_nova", name = "移动冰球·被动", needwood = "0", needgold = "0", desc = "等级1：攻击命中时有12%概率向目标方向释放冰球。冰球以360速度直线移动，每0.5秒对300范围造成全属性×2伤害。 等级2：冰球速度提高50%至540；每碰撞一个不同敌人，周期基础伤害提高5%，最多10次。 等级3：冰球影响半径扩大至350；飞行结束时爆炸，对350范围造成一次全属性×3伤害。 等级4：完整继承等级3效果，无额外变化。 等级5：冰球自动追踪最大移动距离内的随机敌人；最大移动距离提高50%，每移动100码周期基础伤害提高10%。目标死亡后直线飞向其死亡位置并爆炸。", icon = "crystal_maiden_crystal_nova", source_id = "proto_frost_nova" },
    { tooltip_id = "ability:ability_survival_holy_pulse", tooltip_type = "ability", id = "ability_survival_holy_pulse", name = "元气弹·被动", needwood = "0", needgold = "0", desc = "等级1：攻击命中时有12%概率向英雄攻击射程内最近的最多5个敌人发射追踪元气弹。每颗命中造成触发时全属性×4纯粹伤害。 等级2：每颗元气弹命中时恢复英雄5%最大生命值，按实际命中数量分别恢复。 等级3：基础目标上限提高至7个；每次触发另有10%概率将本次目标上限提高至9个。 等级4：完整继承等级3效果，无额外变化。 等级5：每颗元气弹命中时独立有20%概率爆炸，对目标中心250范围内所有敌人额外造成该颗基础伤害60%的纯粹伤害；原目标也会重复承受爆炸伤害。", icon = "keeper_of_the_light_illuminate", source_id = "proto_holy_pulse" },
    { tooltip_id = "ability:ability_survival_ice_cone", tooltip_type = "ability", id = "ability_survival_ice_cone", name = "寒冰锥·被动", needwood = "0", needgold = "0", desc = "等级1：普通攻击命中时有15%概率触发：以目标位置为中心，在500范围内立即落下冰锥，之后每秒落下1次，共3次。每次造成触发时全属性总和×1纯粹伤害。暴风雪结束前不能再次触发。 等级2：每次落冰使命中的敌人攻击速度降低20%，持续3秒；不可叠加，再次命中刷新持续时间。 等级3：每次落冰对每个命中的敌人独立进行判定，有20%概率冻结1秒；保留20%攻击速度降低。 等级4：完整继承等级3效果，无额外变化。 等级5：落冰次数增加至5次，暴风雪持续时间增加至5秒；攻击速度降低提高至40%，其他效果不变。", icon = "crystal_maiden_freezing_field", source_id = "proto_ice_cone" },
    { tooltip_id = "ability:ability_survival_magic_slingshot", tooltip_type = "ability", id = "ability_survival_magic_slingshot", name = "魔法弹弓·被动", needwood = "0", needgold = "0", desc = "等级1：普通攻击命中时有10%概率触发：向英雄当前攻击射程内最近的5名敌人各发射一颗石弹。石弹命中造成全属性总和×3纯粹伤害并眩晕0.1秒。 等级2：眩晕时间延长至1秒；选敌时优先选择当前未被眩晕的敌人，不足5名时再由已眩晕敌人补足。 等级3：石弹命中瞬间若目标已处于眩晕状态，本颗石弹伤害提高至全属性总和×6；先结算旧眩晕增伤，再施加本次眩晕。 等级4：完整继承等级3效果，无额外变化。 等级5：石弹命中后尝试在目标位置生成半径200的碎石区，持续3秒。区域每秒造成全属性总和×1.2纯粹伤害，区域内敌人移动速度降低30%；多个区域减速不叠加，离开全部区域立即恢复。仍处于已有碎石区内的目标不会重复生成新区。", icon = "tiny_toss", source_id = "proto_magic_slingshot" },
    { tooltip_id = "ability:ability_survival_meteor", tooltip_type = "ability", id = "ability_survival_meteor", name = "陨石坠落·被动", needwood = "0", needgold = "0", desc = "等级1：普通攻击命中时有12%概率在目标当时的位置坠落一颗陨石。落地后原地爆炸，不会滚动，对500范围造成触发时全属性×3纯粹伤害。陨石活动期间不能再次触发。 等级2：陨石落地后留下500范围熔岩区域，持续3秒；落地后的第1、2、3秒各造成一次触发时全属性×1纯粹伤害。 等级3：熔岩区域内的敌人降低30%移动速度；多个区域的减速不叠加，离开所有区域立即移除。 等级4：完整继承等级3效果，无额外变化。 等级5：第一颗陨石落地0.5秒后，在同一位置落下第二颗陨石。第二颗爆炸和熔岩伤害均为第一颗的80%；两片熔岩独立造成伤害。", icon = "invoker_chaos_meteor", source_id = "proto_meteor" },
    { tooltip_id = "ability:ability_survival_monkey_king_agility", tooltip_type = "ability", id = "ability_survival_monkey_king_agility", name = "齐天大圣专属：身外化身", needwood = "0", needgold = "0", desc = "十转激活。终极塔继承英雄最终攻击力和暴击伤害；终极塔自身D技能仍可移动。", icon = "monkey_king_mischief", source_id = "skill_monkey_king_agility" },
    { tooltip_id = "ability:ability_survival_monkey_king_exclusive", tooltip_type = "ability", id = "ability_survival_monkey_king_exclusive", name = "齐天大圣专属：棍式", needwood = "0", needgold = "0", desc = "一转激活。主攻击命中时有10%概率朝目标方向挥出1200×200棍击，对范围敌人造成全属性×30与最大生命10%的纯粹伤害；生命伤害每个敌人最多3次。", icon = "monkey_king_boundless_strike", source_id = "skill_monkey_king_exclusive" },
    { tooltip_id = "ability:ability_survival_monkey_king_fury", tooltip_type = "ability", id = "ability_survival_monkey_king_fury", name = "齐天大圣专属：混沌神猿", needwood = "0", needgold = "0", desc = "三转激活。暴击伤害为2000%，攻击间隔减少0.1秒；每60秒永久复利增加2%全属性，并召唤唯一永久镜像分身守家。分身拥有Q技能，完整继承本体暴击率，并额外获得1000%暴击伤害。", icon = "monkey_king_jingu_mastery", source_id = "skill_monkey_king_fury" },
    { tooltip_id = "ability:ability_survival_monkey_king_swiftness", tooltip_type = "ability", id = "ability_survival_monkey_king_swiftness", name = "齐天大圣专属：齐天", needwood = "0", needgold = "0", desc = "六转激活。暴击率增加20%，最终攻击力使用独立三倍乘区；仅本体主普通攻击实际暴击时对主目标追加全属性×5纯粹伤害。", icon = "monkey_king_tree_dance", source_id = "skill_monkey_king_swiftness" },
    { tooltip_id = "ability:ability_survival_poison_cloud", tooltip_type = "ability", id = "ability_survival_poison_cloud", name = "毒云·被动", needwood = "0", needgold = "0", desc = "等级1：普通攻击命中时，12%概率在目标位置生成400范围毒云，持续5秒；第1至第5秒各造成一次触发时全属性总和×1纯粹伤害。毒云活动期间同一英雄不会再次触发毒云。 等级2：毒云每次整秒伤害命中使敌人的实时总护甲降低20%，最多3层（60%）；离开毒云或毒云消失时立即恢复毒云降低的护甲。 等级3：触发概率提高至20%，毒云持续时间增加至7秒，因此第1至第7秒各造成一次伤害。 等级4：完整继承等级3效果，无额外变化。 等级5：毒云中的敌人死亡时，以死亡位置为中心对300范围造成一次触发时全属性总和×3纯粹伤害；死亡爆炸可继续引发毒云内敌人的连锁爆炸。", icon = "viper_nethertoxin", source_id = "proto_poison_cloud" },
    { tooltip_id = "ability:ability_survival_rogue_reward", tooltip_type = "ability", id = "ability_survival_rogue_reward", name = "肉鸽奖励", needwood = "0", needgold = "0", desc = "打开肉鸽三选一奖励。建造者开局固定显示在G键槽位，成功打开后移除。", icon = "invoker_invoke", source_id = "builder_rogue_reward" },
    { tooltip_id = "ability:ability_survival_shadow_fiend_raze", tooltip_type = "ability", id = "ability_survival_shadow_fiend_raze", name = "影魔专属：影压", needwood = "0", needgold = "0", desc = "一转后激活。普通攻击命中时有10%概率在目标位置释放250范围影压。影压先增加1层再造成纯粹伤害，1至5层分别为全属性×27.5、×30、×32.5、×35、×37.5；最多5层，每层独立持续3秒。", icon = "nevermore_shadowraze1", source_id = "skill_shadow_fiend_raze" },
    { tooltip_id = "ability:ability_survival_void_pulse", tooltip_type = "ability", id = "ability_survival_void_pulse", name = "虚空震爆·被动", needwood = "0", needgold = "0", desc = "等级1：普通攻击命中时有15%概率从攻击者位置释放龙卷风。龙卷风以500速度追踪原攻击目标，第一次到达后附着跟随目标；目标死亡则停在死亡位置。持续3秒，在生成时及第1、2秒实时读取全属性，对中心300范围造成全属性×2纯粹伤害。 等级2：完整继承等级1效果，无额外变化。 等级3：龙卷风中心600范围内的敌人持续降低20%移动速度；被主龙卷伤害命中的敌人在仍处于该范围时额外降低15%，总计35%，离开范围立即移除。 等级4：完整继承等级3效果，无额外变化。 等级5：主龙卷结束时，按仍存活的已命中不同目标数量在结束位置生成小龙卷。小龙卷随机选择这些目标的方向，以相同速度移动2秒，每秒造成主龙卷60%的实时属性伤害，并仅施加20%范围减速。", icon = "invoker_tornado", source_id = "proto_void_pulse" },
    { tooltip_id = "ability:airspace_overlord_lv01", tooltip_type = "ability", id = "airspace_overlord_lv01", name = "空域霸主LV1", needwood = "0", needgold = "0", desc = "500范围内敌方单位最终承伤提高20%；飞行敌人攻击速度额外降低20%", icon = "", source_id = "airspace_overlord_lv01" },
